174		}
175		s.running = false
176		s.runningMu.Unlock()
177	
178		// Cancel all job contexts
179		s.jobsMu.RLock()
180		for _, rj := range s.jobs {
181			if rj.cancelFn != nil {
182				rj.cancelFn()
183			}
184		}
185		s.jobsMu.RUnlock()
186	
187		// Signal stop and wait for jobs to finish
188		close(s.stopCh)
189	
190		done := make(chan struct{})
191		go func() {
192			s.wg.Wait()
193			close(done)
194		}()
195	
196		select {
197		case <-done:
198			return nil
199		case <-ctx.Done():
200			return ctx.Err()
201		}
202	}
